@startuml

class Customer {
  + name : string
  + dateOfBirth : date
  + address : string
  + taxCode : string
}

class Broker {
  + brokerId : int
  + name : string
}

class Contract {
  + contractId : int
  + policyType : string
  + signingDate : date
  + insuredAmount : float
  + premium : float
  + coverageStartDate : date
  + coverageEndDate : date
}

abstract class Policy {
  + policyNumber : int
  + description : string
}

class LifePolicy {}
class CarLiabilityPolicy {}
class TheftPolicy {}

class Claim {
  + claimId : int
  + claimDate : date
  + status : string
}

class ClaimCase {
  + caseId : int
  + claimDate : date
  + status : string
}

class Estimator {
  + estimatorId : int
  + name : string
  + expertiseArea : string
}

class CompensationDecision {
  + decisionId : int
  + compensationAmount : float
  + paymentDate : date
}

Customer "1" -- "0..*" Broker
Broker "1" -- "1..*" Contract
Customer "1" -- "0..*" Contract
Contract "0..*" -- "1" Policy
Policy "1" -- "0..*" LifePolicy
Policy "1" -- "0..*" CarLiabilityPolicy
Policy "1" -- "0..*" TheftPolicy
Contract "1" -- "0..*" Claim
Claim "1" -- "0..*" ClaimCase
Estimator "1" -- "0..*" ClaimCase
ClaimCase "0..*" -- "0..*" Estimator
ClaimCase "1" -- "1" CompensationDecision

@enduml

